import { Buffer } from 'node:buffer'

export const onePagePdfBase64 = ''

export const secondOnePagePdfBase64 = ''

export const qrPngBase64 = ''

export const onePixelJpegBase64 = ''

export const onePixelPngBase64 = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII='

export function fixtureFile(name, mimeType, base64) {
  return { name, mimeType, buffer: Buffer.from(base64, 'base64') }
}

export function tinyWavFixture(name = 'network-private.wav') {
  const sampleRate = 8000
  const sampleCount = 800
  const dataSize = sampleCount * 2
  const buffer = Buffer.alloc(44 + dataSize)
  buffer.write('RIFF', 0)
  buffer.writeUInt32LE(36 + dataSize, 4)
  buffer.write('WAVE', 8)
  buffer.write('fmt ', 12)
  buffer.writeUInt32LE(16, 16)
  buffer.writeUInt16LE(1, 20)
  buffer.writeUInt16LE(1, 22)
  buffer.writeUInt32LE(sampleRate, 24)
  buffer.writeUInt32LE(sampleRate * 2, 28)
  buffer.writeUInt16LE(2, 32)
  buffer.writeUInt16LE(16, 34)
  buffer.write('data', 36)
  buffer.writeUInt32LE(dataSize, 40)
  return { name, mimeType: 'audio/wav', buffer }
}
